import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;

public class DatabaseQueryCache {
    private final Map<String, String> syncCache;

    public DatabaseQueryCache(int capacity) {
        LinkedHashMap<String, String> lruMap = new LinkedHashMap<>(capacity, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<String, String> eldest) {
                boolean evict = size() > capacity;
                if (evict) {
                    System.out.println("Evicting stale query: " + eldest.getKey());
                }
                return evict;
            }
        };
        // Wrap in synchronized map for safe concurrent usage
        this.syncCache = Collections.synchronizedMap(lruMap);
    }

    public void put(String sql, String result) { syncCache.put(sql, result); }
    public String get(String sql) { return syncCache.get(sql); }

    public static void main(String[] args) {
        DatabaseQueryCache queryCache = new DatabaseQueryCache(2);
        queryCache.put("SELECT * FROM users", "UsersData");
        queryCache.put("SELECT * FROM orders", "OrdersData");

        // Access users query to refresh its recency
        queryCache.get("SELECT * FROM users");

        // Adding third query will evict orders (since users was just accessed)
        queryCache.put("SELECT * FROM products", "ProductsData");
    }
}

